/* Generated by gen_bench.py. Do not edit by hand. */
/* pattern=uniform  literal_max=4  cases=40 */
/* dtypes: A=int8 B=uint8 C=int32  acc_bits=32 */
#ifndef URSA_BENCH_H
#define URSA_BENCH_H

#include <stdint.h>

/* NOTE: P, Q and M are struct members here. Do not define them as
   macros in any header included alongside this one. */

/* Plain C style throughout, but valid C++. When compiled as C++,
   the arrays below need external linkage explicitly, which the
   extern declarations in this header provide. */

/* Element types. These MUST mirror data_a_t / data_b_t / data_c_t
   in settings.h. If they diverge, the golden values are invalid. */
typedef int8_t    bench_a_t;
typedef uint8_t   bench_b_t;
typedef int32_t   bench_c_t;

/* Width of the internal MAC accumulator assumed by the golden
   reference; mirrors macc_t. The reference wraps at this width. */
#define BENCH_ACC_BITS 32

/* Fill patterns. bench_fill() reproduces each one on the target. */
#define BENCH_PAT_UNIFORM  0
#define BENCH_PAT_IDENTITY 1
#define BENCH_PAT_CONSTANT 2

#define BENCH_NUM_CASES 40
#define BENCH_MAX_P 1024
#define BENCH_MAX_Q 1024
#define BENCH_MAX_M 1024

typedef struct {
    const char *name;   /* case identifier                     */
    uint8_t     group;  /* 1=square 2=row-irr 3=col-irr        */
    uint16_t    P, Q, M;  /* A is PxM, B is MxQ, C is PxQ    */
    uint32_t    seed;   /* xorshift32 seed                     */
    uint32_t    golden; /* FNV-1a of C, for SDC detection      */
    uint8_t     has_literal;  /* 1 if matrices live in the .c  */
    uint8_t     acc_overflow; /* 1 if the case wraps the accum */
    int32_t     amax, bmax;   /* magnitude caps used for A / B */
    uint8_t     pattern;      /* BENCH_PAT_*; must stay last,  */
                              /* the payload init is positional */
} bench_case_t;

extern const bench_case_t bench_cases[BENCH_NUM_CASES];


/* xorshift32 - must produce the SAME sequence as the Python generator. */
static uint32_t bench_rng_state;

static inline void bench_rng_seed(uint32_t seed) {
    bench_rng_state = (seed == 0u) ? 0x2545F491u : seed;
}

static inline uint32_t bench_rng_u32(void) {
    uint32_t x = bench_rng_state;
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    bench_rng_state = x;
    return x;
}

/* Capped draws. r bounds the magnitude: [-r, r] signed, [0, r]
   unsigned. Capping the inputs is what keeps K * amax * bmax
   inside the accumulator, so the array never wraps. */
static inline bench_a_t bench_rng_a(int32_t r) { return (int8_t)((int32_t)(bench_rng_u32() % (uint32_t)(2*r + 1)) - r); }
static inline bench_b_t bench_rng_b(int32_t r) { return (uint8_t)(bench_rng_u32() % (uint32_t)(r + 1)); }

/* Regenerate A and B on the target. Must match the Python generator,
   including the pattern: only BENCH_PAT_UNIFORM draws A from the
   PRNG, so filling every case with random data would be wrong. */
static inline void bench_fill(const bench_case_t *tc,
                              bench_a_t *A, bench_b_t *B) {
    uint32_t i, r, c;
    bench_rng_seed(tc->seed);

    if (tc->pattern == BENCH_PAT_CONSTANT) {
        /* A and B all ones; the PRNG is not used at all. */
        for (i = 0; i < (uint32_t)tc->P * tc->M; ++i) A[i] = (bench_a_t)1;
        for (i = 0; i < (uint32_t)tc->M * tc->Q; ++i) B[i] = (bench_b_t)1;
        return;
    }

    if (tc->pattern == BENCH_PAT_IDENTITY) {
        /* A is the identity, truncated to P x M. B stays random, so
           the PRNG must not be consumed while filling A. */
        for (r = 0; r < tc->P; ++r)
            for (c = 0; c < tc->M; ++c)
                A[r * tc->M + c] = (bench_a_t)((r == c) ? 1 : 0);
    } else {
        for (i = 0; i < (uint32_t)tc->P * tc->M; ++i) A[i] = bench_rng_a(tc->amax);
    }

    for (i = 0; i < (uint32_t)tc->M * tc->Q; ++i) B[i] = bench_rng_b(tc->bmax);
}

/* FNV-1a over C, to be compared against tc->golden. */
static inline uint32_t bench_checksum(const bench_c_t *C, uint32_t n) {
    uint32_t h = 0x811C9DC5u, i, s;
    for (i = 0; i < n; ++i) {
        uint32_t u = (uint32_t)C[i];
        for (s = 0; s < 32u; s += 8u) {
            h ^= (u >> s) & 0xFFu;
            h *= 0x01000193u;
        }
    }
    return h;
}

#endif /* URSA_BENCH_H */
